# Compute sum of column 'Goals' grouped by 'Season'
print(f"🔧 Computing sum of 'Goals' grouped by 'Season'")

# Check if columns exist and operation is valid
if 'Goals' not in df.columns:
    print(f"❌ Error: Column 'Goals' not found")
    print(f"Available columns: {df.columns.tolist()}")
elif 'Season' not in df.columns:
    print(f"❌ Error: Group by column 'Season' not found")
    print(f"Available columns: {df.columns.tolist()}")
elif "sum" not in ['count', 'sum', 'avg', 'min', 'max']:
    print(f"❌ Error: Invalid operation 'sum'. Valid operations: ['count', 'sum', 'avg', 'min', 'max']")
else:
    try:
        if "sum" == "count":
            result = df.groupby('Season')['Goals'].count()
        elif "sum" == "sum":
            result = df.groupby('Season')['Goals'].sum()
        elif "sum" == "avg":
            result = df.groupby('Season')['Goals'].mean()
        elif "sum" == "min":
            result = df.groupby('Season')['Goals'].min()
        elif "sum" == "max":
            result = df.groupby('Season')['Goals'].max()

        print(f"✅ Sum of 'Goals' by 'Season':")
        print(result)

        # Convert to dataframe for consistency
        result_df = result.reset_index()
        result_df.columns = ['Season', f'sum_result']
        print(f"\n🔍 Result as table:")
        print(result_df)

    except Exception as e:
        print(f"❌ Error computing grouped sum: {e}")
        print(f"Column dtypes: {df[['Goals', 'Season']].dtypes}")
